const join=(a,b)=>b?a+' '+b:a;
export const expandedLines=Object.fromEntries(material.map((topics,index)=>[index+3,topics.flat().flatMap(line=>codas[index].map(coda=>join(line,coda)))]));
export const expandedConclusions=material.flatMap((topics,index)=>{
  const seeds=topics.flat();
  return [...seeds.flatMap(line=>closures[index].slice(0,5).map(ending=>join(line,ending))),...seeds.slice(0,28).map(line=>join(line,closures[index][5]))].map(text=>({voice:index+3,text}));
});
export function expandedTurn(voice,topic,variant,reply=false){
  if(voice<3)return null;
  const index=voice-3,lines=material[index][topic];
  return join(lines[reply?1+variant%4:0],codas[index][reply?Math.floor(variant/4):variant]);
}

